<h2>Estimate monthly loan payment</h2><p class="lead">Calculate an estimated EMI, total interest and the first 12 amortization rows.</p><div class="form-grid"><div class="field"><label for="principal">Loan amount</label><input id="principal" type="number" min="0" step="0.01" value="250000"></div><div class="field"><label for="rate">Annual interest rate (%)</label><input id="rate" type="number" min="0" step="0.01" value="8.5"></div><div class="field full"><label for="years">Loan term (years)</label><input id="years" type="number" min="0.08" step="0.01" value="20"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc">Calculate EMI</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Monthly payment</span><strong id="payment">—</strong></div><div class="metric"><span>Total interest</span><strong id="interest">—</strong></div><div class="metric"><span>Total repayment</span><strong id="total">—</strong></div></div><h3>First 12 payments</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>#</th><th>Payment</th><th>Principal</th><th>Interest</th><th>Balance</th></tr></thead><tbody id="schedule"></tbody></table></div></div><p class="helper">Estimate only. Real lender schedules may differ due to fees, compounding conventions, taxes, insurance or rounding.</p>
<script>(()=>{const $=i=>document.getElementById(i),num=i=>parseFloat($(i).value)||0,money=x=>'$'+x.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});function go(){const P=num('principal'),annual=num('rate'),months=Math.max(1,Math.round(num('years')*12)),r=annual/100/12;let pay=r===0?P/months:P*r*Math.pow(1+r,months)/(Math.pow(1+r,months)-1);if(!isFinite(pay)||P<=0){['payment','interest','total'].forEach(i=>$(i).textContent='—');$('schedule').innerHTML='';return}const total=pay*months;$('payment').textContent=money(pay);$('interest').textContent=money(total-P);$('total').textContent=money(total);let bal=P,html='';for(let n=1;n<=Math.min(12,months);n++){const int=bal*r,pr=Math.min(bal,pay-int);bal=Math.max(0,bal-pr);html+=`<tr><td>${n}</td><td>${money(pay)}</td><td>${money(pr)}</td><td>${money(int)}</td><td>${money(bal)}</td></tr>`}$('schedule').innerHTML=html}document.querySelectorAll('input').forEach(x=>x.addEventListener('input',go));$('calc').onclick=go;go()})();</script>
